//! Criterion timing only after functional gate. Synthetic dense OBJ parsed by tobj.
use criterion::{criterion_group,criterion_main,Criterion,black_box};
use kimo_core::threed::{ingest,flat_sah::Index,spatial::Ray};
fn benchmark(c:&mut Criterion){let n=48usize;let mut obj=String::new();for y in 0..=n{for x in 0..=n{obj+=&format!("v {} {} 0\nvt {} {}\nvn 0 0 1\n",x as f64/n as f64,y as f64/n as f64,x as f64/n as f64,y as f64/n as f64);}}for y in 0..n{for x in 0..n{let a=y*(n+1)+x+1;let b=a+1;let d=a+n+2;let e=a+n+1;for t in [[a,b,d],[a,d,e]]{obj+=&format!("f {0}/{0}/{0} {1}/{1}/{1} {2}/{2}/{2}\n",t[0],t[1],t[2]);}}}let imported=ingest::obj(&obj,true).unwrap();let s=&imported.streams[0];let b=Index::build(s).unwrap();let rays=(0..128).map(|i|Ray{origin:[((i*17)%128) as f64/128.,((i*31)%128) as f64/128.,-1.],direction:[0.,0.,1.],t_min:0.,t_max:5.}).collect::<Vec<_>>();for r in &rays{let a=b.raycast(r,false).unwrap();let z=b.raycast(r,true).unwrap();assert_eq!(a.as_ref().map(|h|h.triangle),z.as_ref().map(|h|h.triangle));}let mut group=c.benchmark_group("flat_sah_obj4608_triangles_128rays");group.sample_size(10).warm_up_time(std::time::Duration::from_secs(1)).measurement_time(std::time::Duration::from_secs(2));group.bench_function("bvh_queries",|bencher|bencher.iter(||for r in &rays{black_box(b.raycast(black_box(r),false).unwrap());}));group.bench_function("brute_force_queries",|bencher|bencher.iter(||for r in &rays{black_box(b.raycast(black_box(r),true).unwrap());}));group.finish();}
criterion_group!(benches,benchmark);criterion_main!(benches);
